-- Run as postgres, in number order, one file at a time.

set search_path = naashir, extensions;

-- 1. The sign-up trigger must never be the reason a sign-up fails.
-- auth.users is shared with the other app in this project, and this trigger
-- runs for its new users too: an error here would stop people registering
-- THERE. So a failed insert is reported as a warning and the sign-up goes on.
create or replace function naashir.handle_new_user()
returns trigger
language plpgsql
security definer set search_path = naashir
as $$
begin
  begin
    insert into naashir.profiles (id, email) values (new.id, new.email)
    on conflict (id) do nothing;
  exception when others then
    raise warning 'naashir.handle_new_user: no profile created for % (%)', new.id, sqlerrm;
  end;
  return new;
end;
$$;

-- 2. People who registered before today have no row yet, and the trigger only
-- fires for new ones. Without a profile they could sign in but not create an
-- invitation.
insert into naashir.profiles (id, email)
select id, email from auth.users
on conflict (id) do nothing;

-- 3. The schema's own login role, when it exists, can read and maintain the
-- tables (they are owned by postgres, which created them).
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'naashir_admin') then
    execute 'grant all on all tables in schema naashir to naashir_admin';
    execute 'grant all on all sequences in schema naashir to naashir_admin';
    execute 'grant all on all routines in schema naashir to naashir_admin';
    execute 'alter default privileges in schema naashir grant all on tables to naashir_admin';
    execute 'alter default privileges in schema naashir grant all on sequences to naashir_admin';
    execute 'alter default privileges in schema naashir grant all on routines to naashir_admin';
  end if;
end
$$;

-- 4. Have the Data API pick up the new tables. It still serves them only once
